import("context";"encoding/json";"errors";"net/http";"time";"github.com/jackc/pgx/v5")
func(h *Handler)MetricsCurrent(w http.ResponseWriter,r *http.Request){if h.db==nil{write(w,503,envelope{OK:false,Error:&apiError{Code:"database_unavailable",Message:"Metrics database is not ready"}});return};var raw []byte;err:=h.db.QueryRow(r.Context(),"SELECT to_jsonb(m) FROM (SELECT * FROM system_metrics ORDER BY sampled_at DESC LIMIT 1) m").Scan(&raw);if errors.Is(err,pgx.ErrNoRows){write(w,200,envelope{OK:true,Data:nil});return};if err!=nil{write(w,500,envelope{OK:false,Error:&apiError{Code:"metrics_query_failed",Message:"Unable to read metrics"}});return};var data any;_=json.Unmarshal(raw,&data);write(w,200,envelope{OK:true,Data:data})}
func(h *Handler)MetricsStream(w http.ResponseWriter,r *http.Request){if h.db==nil{http.Error(w,"metrics database unavailable",503);return};flusher,ok:=w.(http.Flusher);if !ok{http.Error(w,"streaming unsupported",500);return};w.Header().Set("Content-Type","text/event-stream");w.Header().Set("Cache-Control","no-cache");w.Header().Set("Connection","keep-alive");w.Header().Set("X-Accel-Buffering","no");ticker:=time.NewTicker(15*time.Second);defer ticker.Stop();send:=func()bool{ctx,cancel:=context.WithTimeout(r.Context(),3*time.Second);defer cancel();var raw []byte;err:=h.db.QueryRow(ctx,"SELECT to_jsonb(m) FROM (SELECT * FROM system_metrics ORDER BY sampled_at DESC LIMIT 1) m").Scan(&raw);if errors.Is(err,pgx.ErrNoRows){raw=[]byte("null")}else if err!=nil{return false};_,err=w.Write(append(append([]byte("event: metrics\ndata: "),raw...),[]byte("\n\n")...));if err!=nil{return false};flusher.Flush();return true};if !send(){return};for{select{case<-r.Context().Done():return;case<-ticker.C:if !send(){return}}}}
